<?php
namespace Delnavazan\Platform\Core\Application; use Delnavazan\Platform\Core\Infrastructure\Repository\{InstrumentRepository,CourseRepository};
final class CatalogueService { public function instrument(array $d):int{if(!current_user_can('dzn_manage_courses'))throw new \RuntimeException('Unauthorized');$d['slug']=sanitize_title($d['slug']??'');if(!$d['slug'])throw new \InvalidArgumentException('Slug required');$d['status']=Normalizer::one($d['status']??'active',['active','inactive'],'instrument state');return Creator::create(new InstrumentRepository,$d,'DZN-INS-');} public function course(array $d):int{if(!current_user_can('dzn_manage_courses'))throw new \RuntimeException('Unauthorized');$i=(new InstrumentRepository)->usable(Normalizer::id($d['instrument_id']));if(!$i)throw new \InvalidArgumentException('Usable Instrument required');$d['course_type']=Normalizer::one($d['course_type']??'',['standard','introductory'],'course type');$d['status']=Normalizer::one($d['status']??'active',['active','inactive'],'course state');$d['default_duration_minutes']=Normalizer::count($d['default_duration_minutes']??0,5,480);$d['default_buffer_minutes']=Normalizer::count($d['default_buffer_minutes']??0,0,240);return Creator::create(new CourseRepository,$d,'DZN-CRS-');} }
